from gurobipy import Model, GRB, quicksum

def build_and_solve_bigmart(LEGACY_RECORDS):
    shelf_caps = {}
    for rec in LEGACY_RECORDS:
        if rec['source'].endswith('capacity.csv'):
            shelf_id = rec['values']['ShelfID']
            cap = rec['values']['Capacity']
            if shelf_id in shelf_caps:
                raise ValueError(f'Duplicate shelf id {shelf_id}')
            shelf_caps[shelf_id] = int(cap)
    prod_vals = {}
    prod_wts = {}
    for rec in LEGACY_RECORDS:
        if rec['source'].endswith('products.csv'):
            prod = rec['values']['ProductName']
            val = rec['values']['Value']
            wt = rec['values']['Weight']
            if prod in prod_vals or prod in prod_wts:
                raise ValueError(f'Duplicate product {prod}')
            prod_vals[prod] = int(val)
            prod_wts[prod] = int(wt)
    if not shelf_caps or not prod_vals or (not prod_wts):
        raise ValueError('Missing shelf or product data')
    if set(prod_vals) != set(prod_wts):
        raise ValueError('Mismatch in product value/weight keys')
    shelf_ids = sorted(shelf_caps, key=lambda x: int(x))
    prod_ids = sorted(prod_vals, key=lambda x: int(x))
    m = Model()
    m.Params.MIPGap = 0.0001
    x_vars = m.addVars(shelf_ids, prod_ids, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((prod_vals[j] * x_vars[i, j] for i in shelf_ids for j in prod_ids)), GRB.MAXIMIZE)
    for i in shelf_ids:
        m.addConstr(quicksum((prod_wts[j] * x_vars[i, j] for j in prod_ids)) <= shelf_caps[i], name=f'cap_{i}')
    m.optimize()
    if m.Status == GRB.OPTIMAL:
        print(f'ObjVal: {m.ObjVal}')
        for i in shelf_ids:
            for j in prod_ids:
                v = x_vars[i, j]
                print(f'{v.VarName} {v.X}')
    else:
        print(f'Solver status: {m.Status}')
    return m
m = build_and_solve_bigmart(LEGACY_RECORDS)